from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent
manifest=json.loads((ROOT/'manifest.json').read_text()) if (ROOT/'manifest.json').exists() else None
def run():
 manifest=json.loads((ROOT/'manifest.json').read_text())
 targets={a['id']:(ROOT/a['svg']).read_text() for a in manifest['targets']}
 refs={name:(ROOT/'references/svg'/(name+'.svg')).read_text() for name in manifest['references']}
 def icon(name,reference=False):return '<span class="icon" aria-hidden="true">'+(refs if reference else targets)[name]+'</span>'
 def button(name,label='',reference=False,cls='',aria=''):
  return '<button class="touch '+cls+'" aria-label="'+html.escape(aria or label or name)+'">'+icon(name,reference)+(('<span>'+label+'</span>') if label else '')+'</button>'
 header='<header><strong>bemem.</strong>'+button('search',reference=True,cls='frameless search',aria='Search cards')+'<span class="spacer"></span>'+button('account',reference=True,cls='account',aria='Account')+'</header>'
 tiles=''.join('<article class="tile">'+icon(a['id'])+'<h3>'+a['id'].replace('-',' ').title()+'</h3><div class="sizes">'+''.join('<div style="--size:'+str(size)+'px">'+icon(a['id'])+'<small>'+str(size)+'</small></div>' for size in [16,20,24,32])+'</div><p>'+a['note']+'</p><a href="'+a['svg']+'">SVG</a> · <a href="'+a['png']+'">PNG</a></article>' for a in manifest['targets'])
 menu='<div class="menu">'+''.join(button(n,label) for n,label in [('add-card','Add Card'),('decorate','Decorate'),('policy','Policy'),('login','Login')])+'</div>'
 mockups=[('Home Account menu',header+'<div class="canvas"><div class="sample-card">Test Member</div></div>'+menu,'Only proposed leading menu glyphs are new. Search and Account remain source-based anchors; all four labels stay.'),
 ('Decorate contextual controls','<header><b>Decorate</b><span class="spacer"></span><small>Cozy Cute</small></header><div class="grid"><div class="sample-card">Test Member</div><div class="context">'+button('delete',cls='destructive',aria='Delete selected decoration')+button('rotate',aria='Rotate selected decoration90degrees')+'</div><div class="selected-tile">Selected<br>1×1 item</div></div><div class="toolbar"><button>Cancel</button><button>Undo</button><button>Redo</button><button class="primary">Save</button></div>','Delete remains left; Rotate remains right. Context glyphs22px,48px hit areas. Existing grid/drawer/editor are not changed or rebuilt here.'),
 ('Create Card Detail edit action','<div class="detail"><div class="detail-header"><b>Test Member</b>'+button('edit',cls='detail-edit',aria='Edit Card')+'<span class="spacer"></span>'+button('close',reference=True,aria='Close Card Detail')+'</div><div class="scan-panel">Existing scan-code region<br><small>Layout placeholder only · not scannable</small></div><div class="card-row"><small>No expiry</small><div class="small-card">Test Member</div><div>'+button('flip',reference=True,aria='Switch card front and back')+'<small>Front</small></div></div><p class="number">00123456</p><button class="wide">View Card History &amp; Receipts</button></div>','Existing Create context uses Edit beside the name. Default16px icon reflects AddCardIcon sizing; inspect20px optically before any future implementation.')]
 panels=''.join('<article><h3>'+name+'</h3><div class="phone">'+body+'</div><p>'+note+'</p></article>' for name,body,note in mockups)
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>bemem · existing family refinement</title><style>
@font-face{font-family:Manrope;src:url("../../assets/fonts/lagoon/manrope.ttf") format("truetype");font-display:swap}:root{--ink:#263943;--paper:#f4f5f7;--line:#cbd4da}*{box-sizing:border-box}body{margin:0;background:#e8edf0;color:var(--ink);font:15px Manrope,system-ui}main{max-width:1280px;margin:auto;padding:24px}h1{font-size:28px}p{line-height:1.6}a{color:inherit}button{font:inherit;cursor:pointer;color:inherit;background:#f9fafb;border:1px solid var(--line);border-radius:14px;min-height:48px;padding:8px 12px}button:active{opacity:.72}button:focus-visible,a:focus-visible{outline:3px solid var(--ink);outline-offset:2px}.links{display:flex;flex-wrap:wrap;gap:16px}.note{padding:14px 18px;border-radius:14px;background:#f7f8fa}.board{display:block;width:100%;height:auto;margin:16px 0}.anchors{display:flex;flex-wrap:wrap;gap:24px;align-items:center;background:var(--paper);padding:18px;border-radius:18px}.anchors figure{margin:0;text-align:center}.anchors figcaption{font-size:12px;margin-top:8px}.icon{display:inline-flex;width:24px;height:24px;align-items:center;justify-content:center;flex:none}.icon svg{width:100%;height:100%;color:inherit}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.tile{background:var(--paper);border-radius:18px;padding:20px}.tile>.icon{width:40px;height:40px}.tile p{font-size:13px}.tile h3{font-size:17px}.sizes{display:flex;gap:16px;align-items:center;margin:16px 0}.sizes .icon{width:var(--size);height:var(--size)}.sizes small{display:block;text-align:center;margin-top:8px;font-size:11px}.mocks{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:20px}.mocks>article>p{font-size:13px;max-width:390px}.phone{max-width:390px;width:100%;background:var(--paper);border:1px solid var(--line);border-radius:24px;overflow:hidden}.touch{width:48px;height:48px;min-width:48px;min-height:48px;display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:0}.touch:has(span:nth-child(2)){width:auto}header{display:flex;align-items:center;gap:4px;min-height:70px;padding:14px 20px 8px}header strong{font-size:30px;letter-spacing:-1.2px;line-height:38px;white-space:nowrap}.spacer{flex:1}.frameless{border:0;background:none}.search .icon{width:20px;height:20px}.account{border-radius:50%;background:none}.account .icon{width:24px;height:26px}.canvas{height:170px;margin:16px}.sample-card{width:162.4px;height:106.4px;padding:15px;border-radius:14px;background:#a8bfc4;font-size:13px}.menu{width:224px;margin:-155px 20px 24px auto;position:relative;padding:6px 0;border:1px solid var(--line);background:#f7f7fa;border-radius:20px;box-shadow:0 8px 24px #23303c29}.menu .touch{width:100%;border:0;border-radius:0;background:none;justify-content:flex-start;padding:12px 20px;height:auto}.menu .icon{width:20px;height:20px}.grid{height:280px;margin:16px;position:relative;background-image:radial-gradient(#c7cfd6 .7px,transparent .7px);background-size:28px 28px}.context{display:flex;gap:24px;margin-top:20px}.context .icon{width:22px;height:22px}.destructive{color:#b42318}.selected-tile{width:56px;height:56px;margin:10px 0 0 42px;border:1px solid #627784;text-align:center;padding-top:8px;border-radius:4px;font-size:10px}.toolbar{display:flex;gap:4px;padding:8px 12px}.toolbar button:nth-child(1){width:60px}.toolbar button:nth-child(2),.toolbar button:nth-child(3){width:56px}.toolbar button:last-child{flex:1}.toolbar button{padding:4px;font-size:12px}.primary{background:#405764;color:white}.detail{padding:20px;background:#f7f7fc;border-radius:24px 24px 0 0}.detail-header{display:flex;align-items:center;gap:4px}.detail-header>b{font-size:18px}.detail-header button{border:0;background:transparent}.detail-edit .icon{width:16px;height:16px}.scan-panel{height:194px;border-radius:20px;background:white;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;margin:16px 0 8px;font-size:12px;color:#52636d}.scan-panel small{font-size:10px}.card-row{display:flex;gap:6px;align-items:center;justify-content:space-between}.small-card{width:162.4px;height:106.4px;border-radius:14px;background:#a8bfc4;padding:10px;flex:none;font-size:11px}.card-row>small{font-size:10px}.card-row .icon{width:16px;height:16px}.card-row>div:last-child{display:flex;flex-direction:column;align-items:center}.card-row small{font-size:10px}.number{text-align:center;font-size:22px;letter-spacing:2px;margin:8px 0}.wide{width:100%;font-size:12px}.status{min-height:24px;font-size:12px} @media(max-width:700px){main{padding:14px}.mocks{grid-template-columns:1fr}.phone{margin:auto}.anchors{gap:18px}}@media(max-width:350px){.card-row{flex-wrap:wrap;justify-content:center}.gallery{grid-template-columns:1fr}header{flex-wrap:wrap}}
</style></head><body><main><h1>bemem · existing icon family refinement</h1><p>Seven actions only. Same existing family—not a new icon system, no A/B/C selection.</p><div class="note">Reference anchors below come from current production code. New proposals use the same24-unit,2-unit rounded-outline language and existing ink#263943. Preview only; no app action or data access.</div><div class="links"><a href="REVIEW.md">Style extraction and clarity notes</a><a href="manifest.json">SVG / PNG manifest</a><a href="validation.json">Validation</a></div><h2>Existing reference anchors</h2><div class="anchors">ANCHORS</div><p>Camera/Flip/Share/Close paths are copied for reference only, with their existing Lucide attribution. Search/Account are SVG reconstructions of the Native View geometry; Account has export padding. These anchors are not redesign proposals.</p><h2>Reference / Before / After</h2><a href="sheets/comparison.png"><img class="board" src="sheets/comparison.png" alt="Existing reference anchors alongside three refined and four added icons"></a><h2>Seven proposals on light UI</h2><div class="gallery">TILES</div><h2>Small-size checks</h2><p>PNG board:16/20/24/32 physical pixels at1x. HTML uses matching CSS logical sizes. Neither is a measured Samsung dp screenshot; view at100% zoom. Current production AddCardIcon uses16px, so inspect Edit and Policy particularly carefully.</p><a href="sheets/actual-size.png"><img class="board" src="sheets/actual-size.png" alt="Seven icons at16,20,24,32 pixels on light and dark"></a><h2>Placement studies · existing UI contexts</h2><div class="mocks">PANELS</div><p class="status" id="status" aria-live="polite">Mockup buttons are review-only.</p><p>Keep Add Card / Decorate / Policy / Login labels. Delete retains safety confirmation; Rotate90 and Edit retain accessible names. Recognition improvements are proposals pending user testing.</p></main><script>document.querySelectorAll('.mocks button').forEach(button=>button.addEventListener('click',()=>{document.getElementById('status').textContent='Preview only: '+(button.getAttribute('aria-label')||button.textContent)+'. No app action was triggered.'}));</script></body></html>'''
 page=page.replace('ANCHORS',''.join('<figure>'+icon(n,True)+'<figcaption>'+('Front/Back' if n=='flip' else n.title())+'</figcaption></figure>' for n in ['search','account','camera','flip','share','close'])).replace('TILES',tiles).replace('PANELS',panels)
 (ROOT/'index.html').write_text(page,encoding='utf-8');print('Gallery created:7 target proposals,6 anchors,3 placement mockups')

if __name__=='__main__':run()
